fn reverse(a: &Vec<char>) -> Vec<char> {
    let n = a.len();
    let mut b = Vec::with_capacity(n); // Create a new vector with the same capacity as the input

    for i in (0..n).rev() { // Iterate from n-1 down to 0
        b.push(a[i]); // Push characters in reverse order
    }

    b // Return the new vector
}